     1	import type { Item } from "./policy.js";
     2	
     3	/**
     4	 * The MHPCO price list states one row per main item type: what the item is
     5	 * insured for, and what insuring it costs. The spec states the two figures
     6	 * together ("Sword: 1000 G insurance value, 100 G base premium"), and the
     7	 * MHPCO revises them together, so they are kept in one row rather than in
     8	 * parallel tables that would have to be kept in step by hand.
     9	 */
    10	interface PriceListRow {
    11	  /** Unstated while no active example has yet fixed this row's figure. */
    12	  readonly insuranceValue?: number;
    13	  readonly basePremium?: number;
    14	}
    15	
    16	const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListRow>> = {
    17	  sword: { insuranceValue: 1000, basePremium: 100 },
    18	  amulet: { insuranceValue: 600, basePremium: 60 },
    19	  staff: { basePremium: 80 },
    20	  potion: { basePremium: 40 },
    21	};
    22	
    23	/** A figure the price list does not state costs and covers nothing. */
    24	const UNSTATED = 0;
    25	
    26	function priceListRowOf(item: Item): PriceListRow {
    27	  return MAIN_ITEM_PRICE_LIST[item.type] ?? {};
    28	}
    29	
    30	/** What the MHPCO charges to insure one item of this type, before modifiers. */
    31	export function basePremiumOf(item: Item): number {
    32	  return priceListRowOf(item).basePremium ?? UNSTATED;
    33	}
    34	
    35	/** What the MHPCO considers one item of this type to be insured for. */
    36	export function insuranceValueOf(item: Item): number {
    37	  return priceListRowOf(item).insuranceValue ?? UNSTATED;
    38	}
